// Python cross-checked results (values verified against CPython semantics)
const cases = [
  ['-7 // 2', -4], ['-7 % 3', 2], ['7 % -3', -2], ['7 // 2', 3],
  ['-7 // -2', 3], ['-7 % -3', -1], ['7.5 // 2', 3], ['-7.5 // 2', -4],
  ['0 // -3', 0], ['-0.0 // 3', 0], ['7 % 3', 1],
  ['-2 ** 2', -4], ['2 ** -1', 0.5], ['2 ** 3 ** 2', 512],
  ['(-2) ** 2', 4], ['-2 ** -2', -0.25], ['2 * -3', -6], ['--5', 5],
  ['1 + 2 * 3', 7], ['10 - 4 - 3', 3], ['20 / 4 / 5', 1],
  ['1 < 2', true], ['2 < 1', false], ['1 < 2 <= 2', true],
  ['1 < 2 <= 1', false], ['3 > 2 > 1', true], ['3 > 2 > 2', false],
  ['1 == 1 != 0', true], ['1 < 2 < 3 < 4', true],
  ['(1 < 2) + 1', 2], ['(2 < 1) * 5', 0], ['(1 < 2) == 1', true],
  ['min(3, 1, 2)', 1], ['max(3, 1, 2)', 3], ['abs(-4)', 4],
  ['min(2 + 3, 2 * 3)', 5], ['max(abs(-9), 2 ** 3)', 9],
  ['.5 + 5.', 5.5], ['1.5e-3 + 1', 1.0015], ['1e2', 100],
  ['x + y', 7, { x: 3, y: 4 }],
  ['a // b * b + a % b', 7, { a: 7, b: 3 }],
  ['a // b * b + a % b', -7, { a: -7, b: 3 }],
];
for (const [src, expected, vars] of cases) {
  assert.equal(evaluate(src, vars), expected, src);
}

