+assert.equal(col('abs(1, 2)'), 1);
+assert.equal(col('min()'), 1);
+assert.equal(col('min(1,)'), 7);
+// Division by zero detected before evaluation even inside dead short-circuit? No: parse first
+assert.equal(evaluate('1 > 2 > 1 / 0', {}), false); // comparison short-circuit beats it
+
+// Getter-backed properties read once per occurrence, left-to-right
+{
+  const reads = [];
+  const vars = {};
+  Object.defineProperty(vars, 'a', { get: () => { reads.push('a'); return 2; } });
+  Object.defineProperty(vars, 'b', { get: () => { reads.push('b'); return 5; } });
+  assert.equal(evaluate('a * 10 + b - a', vars), 23);
+  assert.deepEqual(reads, ['a', 'b', 'a']);
+}
+
+// Inherited properties are not readable
+assert.throws(() => evaluate('toString'), ExprError);
+
+// Booleans at top level
+assert.strictEqual(evaluate('1 < 2'), true);
+assert.strictEqual(evaluate('2 < 1'), false);
+
+// Performance: 200k-operand flat chains, well under a second
+for (const [label, src] of [
+  ['sum', '1' + ' + 1'.repeat(200_000)],
+  ['product', '2' + ' * 2 % 3'.repeat(100_000)],
+  ['comparison', '1' + ' < 2'.repeat(100_000)],
+]) {
+  const t = process.hrtime.bigint();
+  const v = evaluate(src);
+  const ms = Number(process.hrtime.bigint() - t) / 1e6;
+  console.log(label, '->', v, `${ms.toFixed(1)}ms`);
+  assert.ok(ms < 1000, label);
+}
+console.log('all checks passed');

