'use strict';
const assert = require('node:assert/strict');
const { evaluate, ExprError } = require('./src/index');

// Python cross-checked results
const cases = [
  ['-7 // 2', -4], ['-7 % 3', 2], ['7 % -3', -2], ['7 // 2', 3],
  ['-7 // -2', 3], ['-7 % -3', -1], ['7.5 // 2', 3], ['-7.5 // 2', -4],
  ['0 // -3', 0], ['7 % 3', 1], ['8 % 2', 0], ['-8 % -2', 0],
  ['-2 ** 2', -4], ['2 ** -1', 0.5], ['2 ** 3 ** 2', 512],
  ['(-2) ** 2', 4], ['-2 ** -2', -0.25], ['2 * -3', -6], ['--5', 5],
  ['1 + 2 * 3', 7], ['10 - 4 - 3', 3], ['20 / 4 / 5', 1],
  ['1 < 2', true], ['2 < 1', false], ['1 < 2 <= 2', true],
  ['1 < 2 <= 1', false], ['3 > 2 > 1', true], ['3 > 2 > 2', false],
  ['1 == 1 != 0', true], ['1 < 2 < 3 < 4', true],
  ['(1 < 2) + 1', 2], ['(2 < 1) * 5', 0], ['(1 < 2) == 1', true],
  ['min(3, 1, 2)', 1], ['max(3, 1, 2)', 3], ['abs(-4)', 4],
  ['min(2 + 3, 2 * 3)', 5], ['max(abs(-9), 2 ** 3)', 9],
  ['.5 + 5.', 5.5], ['1.5e-3 + 1', 1.0015], ['1e2', 100],
  ['x + y', 7, { x: 3, y: 4 }],
  ['a // b * b + a % b', 7, { a: 7, b: 3 }],
  ['a // b * b + a % b', -7, { a: -7, b: 3 }],
];
for (const [src, expected, vars] of cases) {
  assert.equal(evaluate(src, vars), expected, src);
}
assert.strictEqual(evaluate('1 < 2'), true);
assert.strictEqual(evaluate('2 < 1'), false);
assert.ok(Object.is(evaluate('0 // -3'), 0) && 1 / evaluate('0 // -3') > 0, 'positive zero');
assert.ok(1 / evaluate('-8 % 2') > 0, 'positive zero remainder');

// Short-circuit: unknown variable in a dead operand is never read
assert.equal(evaluate('1 > 2 > missing', {}), false);
assert.equal(evaluate('0 == 1 == 1/0', {}), false);
assert.throws(() => evaluate('3 > 2 > missing', {}), ExprError);

// Error columns: 1-based UTF-16 offset of the offending token
const col = (src, vars) => {
  try { evaluate(src, vars); } catch (e) { if (e instanceof ExprError) return e.column; throw e; }
  throw new Error('no error: ' + src);
};
assert.equal(col('1 + @'), 5);
assert.equal(col('  1 +'), 6);          // unexpected end: length + 1
assert.equal(col('  1 +   '), 8);       // trailing whitespace counts
assert.equal(col('alpha + beta', { alpha: 1 }), 9); // unknown variable at identifier
assert.equal(col('6 + 4  // 0'), 8);    // division by zero at operator token
assert.equal(col('6 % 0'), 3);
assert.equal(col('  foo(1, 2)'), 3);    // unknown function at identifier
assert.equal(col('abs(1, 2)'), 1);      // arity at identifier
assert.equal(col('min()'), 1);
assert.equal(col('min(1,)'), 7);        // no trailing commas
assert.equal(col('1 2'), 3);            // no implicit products
assert.equal(col('(1 + 2'), 7);         // unclosed paren -> end
assert.equal(col('1 = 2'), 3);

// Getter-backed properties read once per occurrence, left-to-right
{
  const reads = [];
  const vars = {};
  Object.defineProperty(vars, 'a', { get: () => { reads.push('a'); return 2; } });
  Object.defineProperty(vars, 'b', { get: () => { reads.push('b'); return 5; } });
  assert.equal(evaluate('a * 10 + b - a', vars), 23);
  assert.deepEqual(reads, ['a', 'b', 'a']);
}
// Inherited properties are not readable
assert.throws(() => evaluate('toString'), ExprError);

// Performance: long flat chains, linear and non-recursive
for (const [label, src, expected] of [
  ['sum', '1' + ' + 1'.repeat(200_000), 200_001],
  ['product', '1' + ' * 2 % 3'.repeat(100_000), 2],
  ['comparison', '1' + ' < 2'.repeat(100_000), true],
]) {
  const t = process.hrtime.bigint();
  const v = evaluate(src);
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  console.log(label, '->', v, `${ms.toFixed(1)}ms`);
  assert.equal(v, expected, label);
  assert.ok(ms < 1000, label);
}
console.log('all checks passed');

