  if (is('+') || is('-')) {
    return { type: 'unary', operator: take(), operand: unary() };
  }
  return power();
}

function power() {
  const left = primary();
  if (is('**')) {
    const operator = take();
    return binary(operator, left, unary());
  }
  return left;
}
```

